  var findings=[["SQLi in /login","critical"],["XSS in /search","high"],["missing HSTS","medium"]];
  var f=findings[idx%findings.length];
  return "["+label+"] report: ["+f[1]+"] "+f[0]+" -> remediation ticket #"+(100+idx);
}

